var tokenPattern = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)

// Key names one desired resource: a catalog cell, a resource kind, and a
// logical name unique within the kind.
type Key struct {
	Region string `json:"region"`
	Kind   string `json:"kind"`
	Name   string `json:"name"`
}

// Validate requires a catalog cell and DNS-label kind and name tokens.
func (k Key) Validate() error {
	if !catalog.IsCell(k.Region) || !tokenPattern.MatchString(k.Kind) || !tokenPattern.MatchString(k.Name) {
		return fmt.Errorf("OCI resource key %q is invalid", k.String())
	}
	return nil
}

// String is the stable resource key used in ownership tags.
func (k Key) String() string { return k.Region + "/" + k.Kind + "/" + k.Name }

// subject is the NATS KV key. Every token is restricted to [A-Za-z0-9-].
func (k Key) subject() string { return k.Region + "." + k.Kind + "." + k.Name }

// DriftPolicy decides what a controller does with a non-empty plan.
type DriftPolicy string

const (
	// PolicyEnforce applies the plan to converge OCI to the desired spec.
	PolicyEnforce DriftPolicy = "enforce"
)

func (p DriftPolicy) valid() bool { return p == PolicyEnforce }

// Change is one human-readable step of a plan.
type Change struct {
	Op     string `json:"op"`
	Detail string `json:"detail"`
}

// Plan is the difference between desired and observed state. An empty plan
// means the resource is in sync.
type Plan struct {
	Changes []Change `json:"changes,omitempty"`
}

// Empty reports whether there is no drift.
func (p Plan) Empty() bool { return len(p.Changes) == 0 }

// Add appends one change.
func (p *Plan) Add(op, format string, args ...any) {
	p.Changes = append(p.Changes, Change{Op: op, Detail: fmt.Sprintf(format, args...)})
}

// Target is what a Resource is asked to act on: the key, the ownership proof
// it must stamp or check, and the decoded spec.
type Target[S any] struct {
	Key        Key
	Generation uint64
	SpecDigest string
	Ownership  Ownership
	Spec       S
	// OperationID is durable before Apply/Delete and retained until OCI
	// observation confirms convergence, including after a leader restart.
	OperationID string
	// Deleting is set when the desired record is tombstoned. A resource that
	// is part of a larger object (rules of an NSG, backends of an NLB) reports
	// found=false once none of its managed parts remain.
	Deleting bool
	// Guard re-checks mutation authority. The controller sets it; Apply and
	// Delete call Fence before every individual mutation, so a controller
	// that loses leadership mid-pass stops instead of finishing its plan.
	Guard func(context.Context) error
}

// Fence re-checks mutation authority immediately before one mutation.
func (t Target[S]) Fence(ctx context.Context) error {
	if t.Guard == nil {
		return ErrFenced
	}
	return t.Guard(ctx)
}

// Validate rejects an empty owner or an unknown tag mode.
func (o Ownership) Validate() error {
	if !tokenPattern.MatchString(o.Owner) {
		return errors.New("OCI resource ownership requires a token owner")
	}
	if o.Mode != "" && o.Mode != TagModeFreeform || o.Namespace != "" {
		return errors.New("OCI ownership uses freeform tags; alternate tag configuration is retired")
	}
	return nil
}

// Tags is a resource's freeform and defined tags.
type Tags struct {
	Freeform map[string]string
	Defined  map[string]map[string]any
}

// Stamp returns the ownership tags for key at generation and spec digest.
func (o Ownership) Stamp(key Key, generation uint64, specDigest string) Tags {
	values := map[string]string{
		freeformManagedBy: managedByValue, freeformOwner: o.Owner, freeformResource: key.String(),
		freeformGeneration: strconv.FormatUint(generation, 10), freeformSpecDigest: specDigest,
	}
	if o.Validate() != nil {
		return Tags{}
	}
	return Tags{Freeform: values}
}

// Owns reports whether tags prove this controller owns key. Generation and
// spec digest are not part of the proof: they change when the spec changes
// and are restamped by Apply.
func (o Ownership) Owns(key Key, tags Tags) bool {
	if o.Validate() != nil {
		return false
	}
	return tags.Freeform[freeformManagedBy] == managedByValue && tags.Freeform[freeformOwner] == o.Owner &&
		tags.Freeform[freeformResource] == key.String()
}

// Claimed reports whether tags carry any part of an ownership claim, this
// controller's or another's, in the production ownership tags. A tool that
// stamps ownership onto an existing resource refuses a claimed one it does
// not already own.
func (o Ownership) Claimed(tags Tags) bool {
	return tags.Freeform[freeformManagedBy] != "" || tags.Freeform[freeformOwner] != "" || tags.Freeform[freeformResource] != ""
}

// Stale reports whether owned tags lag the desired generation or digest.
func (o Ownership) Stale(tags Tags, generation uint64, specDigest string) bool {
	want := strconv.FormatUint(generation, 10)
	if o.Validate() != nil {
		return true
	}
	return tags.Freeform[freeformGeneration] != want || tags.Freeform[freeformSpecDigest] != specDigest
}

// Merge overlays ownership tags on existing tags without dropping tags owned
// by other tools.
func (t Tags) Merge(ownership Tags) Tags {
	merged := Tags{Freeform: map[string]string{}, Defined: map[string]map[string]any{}}
	for key, value := range t.Freeform {
		merged.Freeform[key] = value
	}
	for key, value := range ownership.Freeform {
		merged.Freeform[key] = value
	}
	for namespace, values := range t.Defined {
		merged.Defined[namespace] = map[string]any{}
		for key, value := range values {
			merged.Defined[namespace][key] = value
		}
	}
	for namespace, values := range ownership.Defined {
		if merged.Defined[namespace] == nil {
			merged.Defined[namespace] = map[string]any{}
		}
		for key, value := range values {
			merged.Defined[namespace][key] = value
		}
	}
	return merged
}

