// Configure installs the shared limiter and retry policy on an SDK client and
// pins it to the factory region. An existing interceptor still runs, after the
// limiter admits the request. Each retry attempt passes through the limiter.
func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

// ObjectStorage returns a rate-limited Object Storage client.
func (f *Factory) ObjectStorage() (objectstorage.ObjectStorageClient, error) {
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Object Storage client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceObjectStorage)
	client.HTTPClient = Instrument(client.HTTPClient, string(ServiceObjectStorage))
	return client, nil
}

// NetworkLoadBalancer returns a rate-limited NLB client.
func (f *Factory) NetworkLoadBalancer() (networkloadbalancer.NetworkLoadBalancerClient, error) {
	client, err := networkloadbalancer.NewNetworkLoadBalancerClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network load balancer client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNLB)
	return client, nil
}

// LoadBalancer returns a rate-limited flexible (L7) load balancer client. It
// shares the NLB token bucket: both are OCI load balancing.
func (f *Factory) LoadBalancer() (loadbalancer.LoadBalancerClient, error) {
	client, err := loadbalancer.NewLoadBalancerClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI load balancer client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNLB)
	return client, nil
}

// WithAuthority rechecks a durable operation's write authority for every SDK
// mutation attempt, including retries after a lost response or provider error.
// The caller cancels ctx when the claim is lost; reads remain available.
func WithAuthority(ctx context.Context, guard func(context.Context) error) context.Context {
	if guard == nil {
		return ctx
	}
	return context.WithValue(ctx, authorityKey{}, guard)
}

// WithAdmission acquires current write authority for each HTTP mutation attempt
// and holds it until that attempt returns. SDK retries acquire it again.
// Clients must use ConfigureRequestCancellation, as Factory clients do.
func WithAdmission(ctx context.Context, acquire func(context.Context) (func(), error)) context.Context {
	return context.WithValue(ctx, admissionKey{}, acquire)
}

// WithWireAttempt records each dispatch before the final authority admission.
// A missing finish record remains unknown, including after process failure.
func WithWireAttempt(ctx context.Context, begin func(*http.Request) (func(*http.Response, error, bool) error, error)) context.Context {
	return context.WithValue(ctx, wireAttemptKey{}, begin)
}

// RequestContext keeps the SDK retry goroutine joined while the original context
// cancels the HTTP request and backoff. Use with ConfigureRequestCancellation.
func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

func requestAttempt(request *http.Request, now time.Time) (RequestAttempt, error) {
	deadline, ok := request.Context().Deadline()
	if !ok || !now.Before(deadline) || request.URL == nil || request.URL.User != nil {
		return RequestAttempt{}, errors.New("OCI mutation requires its original bounded request deadline and target")
	}
	attempt := RequestAttempt{Method: request.Method, URL: request.URL.String(), IfMatch: request.Header.Get("If-Match"),
		RetryToken: request.Header.Get("opc-retry-token"), StartedAt: now.UTC(), Deadline: deadline.UTC()}
	if request.Body != nil && request.Body != http.NoBody {
		if request.GetBody == nil {
			return RequestAttempt{}, errors.New("OCI mutation cannot checkpoint its exact request body")
		}
		body, err := request.GetBody()
		if err != nil {
			return RequestAttempt{}, err
		}
		defer body.Close()
		attempt.Body, err = io.ReadAll(io.LimitReader(body, maxRecordBytes+1))
		if err != nil || len(attempt.Body) > maxRecordBytes {
			return RequestAttempt{}, errors.Join(errors.New("OCI mutation request exceeds its byte bound"), err)
		}
	}
	return attempt, nil
}

func beginRequest(operation Operation, attempt RequestAttempt, now time.Time) (Operation, int, error) {
	operation.Requests = slices.Clone(operation.Requests)
	for _, previous := range operation.Requests {
		if previous.Uncertain() && !previous.sameRequest(attempt) {
			return Operation{}, 0, errors.New("uncertain original OCI request differs from retry bytes or token")
		}
	}
	for i, previous := range operation.Requests {
		if previous.sameRequest(attempt) {
			if !now.Before(previous.Deadline) {
				return Operation{}, 0, errors.New("original OCI request deadline expired; outcome needs observation")
			}
			// A retry retains the first deadline and exact bytes. A missing
			// outcome after this checkpoint remains uncertain on restart.
			previous.FinishedAt, previous.Status, previous.Sent = time.Time{}, 0, false
			operation.Requests[i] = previous
			return operation, i, nil
		}
	}
	if len(operation.Requests) >= 128 {
		return Operation{}, 0, errors.New("OCI operation request journal exceeds its bound")
	}
	operation.Requests = append(operation.Requests, attempt)
	return operation, len(operation.Requests) - 1, nil

func checkpointRequest(ctx context.Context, request *http.Request, desired *Desired, store Store, epoch uint64, now func() time.Time) (func(*http.Response, error, bool) error, error) {
	if desired.Operation == nil {
		return nil, errors.New("OCI wire request has no durable operation")
	}
	attempt, err := requestAttempt(request, now())
	if err != nil {
		return nil, err
	}
	operation, index, err := beginRequest(*desired.Operation, attempt, now())
	if err != nil {
		return nil, err
	}
	retained, cancel := context.WithDeadline(request.Context(), operation.Requests[index].Deadline)
	*request = *request.WithContext(retained)
	ctx = retained
	desired.Operation = &operation
	*desired, err = store.SaveOperation(ctx, *desired, epoch, now(), false)
	if err != nil {
		cancel()
		return nil, err
	}
	if err := ociclient.LimitAdmission(request.Context(), desired.Operation.Requests[index].Deadline); err != nil {
		cancel()
		return nil, err
	}
	return func(response *http.Response, _ error, sent bool) error {
		if response == nil || response.Body == nil {
			defer cancel()
		} else {
			// OCI decodes the response after dispatch returns. Keep its bounded
			// context live until that body closes rather than canceling early.
			response.Body = retainedRequestBody{ReadCloser: response.Body, cancel: cancel}
		}
		operation := *desired.Operation
		operation.Requests = slices.Clone(operation.Requests)
		attempt := operation.Requests[index]
		attempt.FinishedAt, attempt.Sent = now(), sent
		if response != nil && sent {
			attempt.Status = response.StatusCode
		}
		operation.Requests[index] = attempt
		desired.Operation = &operation
		updated, err := store.SaveOperation(ctx, *desired, epoch, now(), false)
		if err != nil {
			return fmt.Errorf("persist original OCI request outcome: %w", err)
		}
		*desired = updated
		return nil
	}, nil
}

// RecordWorkRequest checkpoints an accepted asynchronous OCI mutation before
// waiting for it, so the next leader can finish observing it before new writes.
func RecordWorkRequest(ctx context.Context, id string) error {
	operation, _ := ctx.Value(operationContextKey{}).(operationContext)
	if operation.record == nil {
		return nil
	}
	return operation.record(ctx, id)
}

// RetryToken derives a stable OCI token for one request within an operation.
// Step must bind the request's target and payload, so different requests never
// share a token. Direct SDK consumers without an operation retain fresh tokens.
func RetryToken(ctx context.Context, step string) string {
	operation, _ := ctx.Value(operationContextKey{}).(operationContext)
	if operation.id == "" {
		return common.RetryToken()
	}
	sum := sha256.Sum256([]byte(operation.id + "\x00" + step))
	return hex.EncodeToString(sum[:])

