type fenceAfter struct{ remaining int }

func (f *fenceAfter) Guard(context.Context, uint64) error {
	if f.remaining <= 0 {
		return errors.New("lost leadership")
	}
	f.remaining--
	return nil
}

func TestApplyReguardsBeforeEveryMutation(t *testing.T) {
	api := &providerState{balancer: LoadBalancer{ID: lbID, Tags: owner.Stamp(key, 0, "")},
		backends: []Backend{observed("10.251.0.21", false), observed("10.251.0.22", false)}}
	store := persistentStore(t)
	spec := Spec{LoadBalancerID: lbID, BackendSet: "terrabase", Backends: []Backend{
		{IP: "10.251.0.21", Port: 9465}, {IP: "10.251.0.22", Port: 9465, Drain: true}, {IP: "10.251.0.23", Port: 9465}}}
	if _, err := Publish(t.Context(), store, key, ociresource.PolicyEnforce, spec); err != nil {
		t.Fatal(err)
	}
	// The controller's own guard plus two mutations, then leadership is
	// lost before the restamp.
	fenced := &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store,
		Ownership: owner, Authority: &fenceAfter{remaining: 12}}
	if _, err := fenced.Reconcile(t.Context(), 1); err == nil {
		t.Fatal("a fenced pass reported success")
	}
	if !slices.Equal(api.calls, []string{"create 10.251.0.23:9465 serving", "update 10.251.0.22:9465 drained"}) {
		t.Fatalf("mutations after losing authority: %v", api.calls)
	}
}

target := Target[S]{Key: desired.Key, Generation: desired.Generation, SpecDigest: desired.SpecDigest,
	Ownership: c.Ownership, Spec: spec, Deleting: desired.Tombstone != nil,
	Guard: func(ctx context.Context) error {
		if err := c.guard(ctx, epoch); err != nil {
			return err
		}
		var err error
		desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
		if err != nil {
			return err
		}
		return c.guard(ctx, epoch)
	}}
bindOperation := func(ctx context.Context) context.Context {
	target.OperationID = desired.Operation.ID
	status.OperationID = target.OperationID
	ctx = ociclient.WithWireAttempt(ctx, func(request *http.Request) (func(*http.Response, error, bool) error, error) {
		return checkpointRequest(request.Context(), request, &desired, c.Store, epoch, c.now)
	})
	return context.WithValue(ociclient.WithAuthority(ctx, target.Fence), operationContextKey{}, operationContext{id: target.OperationID,
		record: func(ctx context.Context, id string) error {
			if id == "" {
				return errors.New("OCI mutation returned no work request")
			}
			if err := c.guard(ctx, epoch); err != nil {
				return err
			}
			if !slices.Contains(desired.Operation.WorkRequests, id) {
				operation := *desired.Operation
				operation.WorkRequests = append(slices.Clone(operation.WorkRequests), id)
				desired.Operation = &operation
			}
			var err error
			desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
			return err
		}})

if err := target.Fence(ctx); err != nil {
	return status, err
}
ctx = bindOperation(ctx)
if err := c.Resource.Apply(ctx, target, observed, found, plan); err != nil {
	return status, fmt.Errorf("apply: %w", err)

func (r Reconciler) mutate(ctx context.Context, target ociresource.Target[Spec], call func() (string, error)) error {
	if err := target.Fence(ctx); err != nil {
		return err
	}
	id, err := call()
	if err != nil {
		return err
	}
	if id == "" {
		return errors.New("load balancer mutation returned no work request")
	}
	return r.API.WaitWorkRequest(ctx, id)

if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
	if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
		if err := guard(ctx); err != nil {
			return fmt.Errorf("OCI %s write authority: %w", service, err)
		}
	}
}

if finish != nil {
	if err := request.Context().Err(); err != nil {
		return deny(err)
	}
	// The durable begin may block; refresh the claim after that write.
	if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
		if guard == nil {
			return deny(errors.New("OCI wire authority is unavailable"))
		}
		if err := guard(request.Context()); err != nil {
			return deny(fmt.Errorf("OCI wire authority: %w", err))
		}
	}
}

func (a sdkAPI) CreateBackend(ctx context.Context, id, backendSet string, backend Backend) (string, error) {
	response, err := a.client.CreateBackend(ociclient.RequestContext(ctx), loadbalancer.CreateBackendRequest{LoadBalancerId: new(id),
		BackendSetName: new(backendSet), OpcRetryToken: new(ociresource.RetryToken(ctx,
			fmt.Sprintf("lb/create/%s/%s/%s/%t/%t", id, backendSet, backend.key(), backend.Drain, backend.offline))),
		CreateBackendDetails: loadbalancer.CreateBackendDetails{IpAddress: new(backend.IP), Port: new(backend.Port),
			Weight: new(defaultWeight), Backup: new(false), Drain: new(backend.Drain), Offline: new(backend.offline)}})
	if err != nil {
		return "", fmt.Errorf("create OCI load balancer backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}
